// MOCK — stands in for a real HubSpot API call.
// In production this looks up all known contacts for the account that fired the intent signal.
const account = {
  accountName: "Example Manufacturing Co.",
  accountId: "ACC-10432",
  topic: "Condition Monitoring", // Condition Monitoring | Energy Insights | Operations Platform
  intentSignalStrength: 82, // 0-100, from mock intent data provider
};

const existingContacts = [
  {
    name: "Avery Morgan",
    title: "Reliability Engineer",
    email: "dana.whitfield@example.com",
    engagementHistory: { emailOpens: 6, emailClicks: 3, siteVisits: 4, lastTouch: "2026-07-14" },
  },
  {
    name: "Jordan Lee",
    title: "Maintenance Manager",
    email: "marcus.ibe@example.com",
    engagementHistory: { emailOpens: 1, emailClicks: 0, siteVisits: 1, lastTouch: "2026-06-02" },
  },
  // Plant Manager is missing on purpose — that's the gap the next node fills.
];

return [{ json: { account, contacts: existingContacts } }];

// MOCK — stands in for a Clay enrichment call.
// Checks whether all 3 target roles exist at the account; mines a new contact for any that's missing.
const { account, contacts } = $input.first().json;
const requiredRoles = ["Reliability Engineer", "Maintenance Manager", "Plant Manager"];
const presentRoles = contacts.map(c => c.title);
const missingRoles = requiredRoles.filter(r => !presentRoles.includes(r));

const enriched = [...contacts];

if (missingRoles.includes("Plant Manager")) {
  enriched.push({
    name: "Taylor Rivera",
    title: "Plant Manager",
    email: "renee.castillo@example.com",
    engagementHistory: { emailOpens: 0, emailClicks: 0, siteVisits: 0, lastTouch: null },
    source: "Clay enrichment — new contact, no engagement yet",
  });
}

return [{ json: { account, contacts: enriched, missingRolesFilled: missingRoles } }];

// Scoring logic, plain language:
// 1) Engagement history is the strongest signal — real behavior beats a title.
// 2) Intent signal strength on the account adds points for everyone at that account.
// 3) Role fit is a tiebreaker/boost, NOT a gate — a Plant Manager with zero engagement doesn't outrank an engaged Reliability Engineer.
const { account, contacts } = $input.first().json;

const roleWeight = {
  "Reliability Engineer": 10,
  "Maintenance Manager": 8,
  "Plant Manager": 6,
};

const scored = contacts.map(contact => {
  const eng = contact.engagementHistory;
  const engagementScore = (eng.emailOpens * 2) + (eng.emailClicks * 5) + (eng.siteVisits * 4);
  const intentScore = account.intentSignalStrength * 0.3;
  const roleFitScore = roleWeight[contact.title] || 5;
  const totalScore = engagementScore + intentScore + roleFitScore;

  let tier = 3;
  if (totalScore >= 45) tier = 1;
  else if (totalScore >= 20) tier = 2;

  return {
    json: {
      account,
      contact,
      engagementScore,
      intentScore,
      roleFitScore,
      totalScore,
      tier,
      engagementCount: eng.emailOpens + eng.emailClicks + eng.siteVisits,
      promotionThreshold: 5,
    }
  };
});

return scored;

// MOCK — plain-language talking points, no jargon.
const { account, contact } = $json;

const painPointByTitle = {
  "Reliability Engineer": "unplanned downtime from bearing/motor failures they can't see coming",
  "Maintenance Manager": "too much time firefighting instead of planning maintenance",
  "Plant Manager": "unplanned downtime hitting the plant's throughput numbers",
};

const talkingPoints = [
  `Open with the trigger: they've been actively looking into ${account.topic} — this isn't a cold call.`,
  `Their likely pain: ${painPointByTitle[contact.title] || "unplanned downtime and reactive maintenance"}.`,
  `What ${account.topic} does for them in one sentence: catches the failure before it takes down the line.`,
  `Ask: "What's driving the timing on this — is something already breaking, or are you getting ahead of it?"`,
];

return [{ json: { ...$json, talkingPoints } }];

const { account, contact } = $json;
const firstName = contact.name.split(" ")[0];

const draftEmail = {
  subject: `${firstName}, saw your team looking into ${account.topic}`,
  body: `Hi ${firstName},\n\nNoticed ${account.accountName} has been looking into ${account.topic} recently. For a ${contact.title}, the reason that usually surfaces is unplanned downtime that's hard to catch early.\n\nWorth a 15-minute call to see if it's a fit?\n\n[Rep name]`,
};

const draftInMail = {
  subject: `Quick question on ${account.topic}`,
  body: `Hi ${firstName} — saw the ${account.topic} research from ${account.accountName}. Happy to share how similar plants are using it if useful.`,
};

return [{ json: { ...$json, draftEmail, draftInMail } }];

// Match priority: industry first, product/pain-point as tie-breaker.
// NOTE: these are real, published Industrial Automation Co. case studies (not fabricated) — swap in more as they're published.
const caseStudyLibrary = [
  { industry: "Steel", product: "Condition Monitoring", title: "Example Steel Customer cuts equipment vibration ~40% with preventive maintenance driven by Condition Monitoring data", url: "https://example.com/sample-case-study" },
  { industry: "Manufacturing (Coatings)", product: "Condition Monitoring", title: "Example Coatings Customer prevents 564 hours of downtime and $150K in losses on powder coating line motors", url: "https://example.com/sample-case-study" },
  { industry: "Chemical/Fertilizer", product: "Condition Monitoring", title: "Example Process Customer avoids a $69K+ loss by catching a faulty blower with AI-driven vibration monitoring", url: "https://example.com/sample-case-study" },
];

const accountIndustry = "Steel"; // mock account attribute
const matched = caseStudyLibrary.find(c => c.industry === accountIndustry && c.product === $json.account.topic)
  || caseStudyLibrary.find(c => c.industry === accountIndustry)
  || caseStudyLibrary[0];

return [{ json: { ...$json, matchedCaseStudy: matched } }];

const cadencePlan = [
  { day: 1, action: "Call + send drafted email same day" },
  { day: 3, action: "LinkedIn InMail if no response" },
  { day: 5, action: "Second call attempt, reference case study" },
  { day: 8, action: "Breakup email if still no response" },
];

return [{ json: { ...$json, cadencePlan } }];

// MOCK — stands in for a real Slack API call notifying the assigned rep.
const slackMessage = {
  channel: "#hot-leads",
  text: `\uD83D\uDD25 Tier 1 lead: ${$json.contact.name} (${$json.contact.title}) at ${$json.account.accountName} — score ${$json.totalScore}. Why: strong ${$json.account.topic} intent + real engagement. Full battle-pack: [link to HubSpot record]`,
};

return [{ json: { ...$json, slackMessage } }];

// This is the system of record. Slack notifies the rep; HubSpot holds the full battle-pack.
const battlePack = {
  account: $json.account.accountName,
  contact: $json.contact.name,
  title: $json.contact.title,
  tier: 1,
  score: $json.totalScore,
  talkingPoints: $json.talkingPoints,
  draftEmail: $json.draftEmail,
  draftInMail: $json.draftInMail,
  matchedCaseStudy: $json.matchedCaseStudy,
  cadencePlan: $json.cadencePlan,
  writtenTo: "HubSpot record (system of record) — Slack notifies, HubSpot holds",
};

return [{ json: { ...$json, hubspotBattlePack: battlePack } }];

const firstName = $json.contact.name.split(" ")[0];
const lightEmail = {
  subject: `Quick resource on ${$json.account.topic}`,
  body: `Hi ${firstName}, saw you looking into ${$json.account.topic} — sharing a quick resource in case it's useful. Let me know if you'd like to talk.`,
};

return [{ json: { ...$json, assignedRep: "Same rep as account owner", lightEmail } }];

// MOCK — simulates an inbound engagement event (open/click/visit) bumping the counter.
const simulatedNewEngagementEvents = 3;
const engagementCount = ($json.engagementCount || 0) + simulatedNewEngagementEvents;

return [{ json: { ...$json, engagementCount } }];

const audienceSegment = {
  platform: "LinkedIn Ads (Mock)",
  segmentName: `${$json.account.topic} - Tier 3 Nurture`,
  accounts: [$json.account.accountName],
  titles: [$json.contact.title],
  targetingParameters: { industry: "Manufacturing", companySizeMin: 200, topic: $json.account.topic },
};

return [{ json: { ...$json, audienceSegment } }];
